export type RepositoryPublicationState = "complete" | "needs_review";

/**  Who answered a permission request or a question. */
export type ResolvedBy = "user" | 
/**  The permission policy, under the chat's autonomy. */
"auto" | 
/**  The agent withdrew it. */
"agent" | 
/**  Its turn ended or was cancelled. */
"turn" | 
/**  Recovery, or the agent's process ended. */
"system" | "other";

export type RevertPreview = {
	token: string,
	checkpoint_id: string,
	files: ChangedFile[],
	expires_at: number,
	warnings: string[],
};

export type RevertResult = {
	applied: string[],
	/**  A partial failure is explicit; the caller must not report full success. */
	error: string | null,
	/**
	 *  Durable recovery groups in the profile's data folder, encrypted for Account profiles.
	 *  A failed finalization also names any transient working-folder copy that was preserved.
	 */
	recovery_paths: string[],
};

/**  How much of a damaged database made it into the database that replaced it. */
export type Salvage = 
/**
 *  Every table read back without an error, so nothing is missing: the damage was in pages no
 *  row lives in (unused pages, a broken index), which the copy rebuilt.
 */
{ type: "complete" } | 
/**
 *  Some rows could not be read, or were dropped because the row they belong to was lost (a
 *  chat's events, when the chat's page was unreadable), or lost a reference to such a row (a
 *  chat whose folder was lost stays in its project, outside any folder). `tables` names those
 *  tables, in schema order. It is empty when which ones isn't known: part of the schema itself
 *  was unreadable (and may have listed tables auracode doesn't know of), or the record of the
 *  repair could not be read.
 */
{ type: "partial"; tables: string[] } | 
/**  Nothing could be read, so the new database started out empty. */
{ type: "nothing" };

export type SaveProjectMemory = {
	project_id: string,
	expected_revision: string | null,
	markdown: string,
	reason: string,
};

export type SearchResults = {
	chats: ChatSearchHit[],
	projects: ProjectSearchHit[],
};

/**  The complete persisted prompt currently saving its checkpoint before dispatch. */
export type SendingPrompt = {
	prompt_id: string,
	text: string,
	parts: PromptPart[],
	created_at: number,
};

export type SessionControl = {
	requested?: string | null,
	effective?: string | null,
	pending?: string | null,
	choices?: SessionControlChoice[],
	native_mode?: string | null,
	note?: string | null,
};

export type SessionControlChange = { type: "access"; value: string } | { type: "workflow"; value: string; implementation_approved?: boolean };

export type SessionControlChoice = {
	value: string,
	name: string,
	description: string | null,
	legacy_autonomy: Autonomy | null,
};

/**  Runtime native control choices, independent from legacy autonomy. */
export type SessionControls = {
	version?: number,
	access?: SessionControl,
	workflow?: SessionControl,
};

/**  Live header state of a chat. Never stored; coalesced to at most one per frame. */
export type SessionInfo = {
	worktree_setup?: WorktreeSetupAttempt | null,
	status: SessionStatus,
	/**  What is happening now: "Starting Hermes", "Stopping the turn; press Esc again to force stop". */
	detail: string | null,
	native_session_id: string | null,
	agent_name: string | null,
	agent_version: string | null,
	title: string | null,
	/**  Display labels of the current Model, Effort and Mode choices. */
	model: string | null,
	effort: string | null,
	mode: string | null,
	autonomy: Autonomy,
	/**  Some queued prompts are held ("Send queued" shows). */
	queue_held: boolean,
	/**
	 *  Increments when capabilities, options, slash commands or the autonomy state change: the UI
	 *  refetches `chat_lists`.
	 */
	revision: number,
	/**
	 *  Why the queued prompts are not going to the agent yet, while any are queued. `None` with
	 *  prompts queued means the next one is on its way.
	 */
	queue_wait: QueueWait | null,
	/**
	 *  The prompt on its way to the agent while its folder checkpoint saves: shown as sending in
	 *  the transcript, not in the queue. `None` once it went, or when a stop or a failed
	 *  checkpoint put it back in the queue, held.
	 */
	sending?: SendingPrompt | null,
	/**
	 *  The added account ([`agents::AgentAccount`]) the current or last start signed in with.
	 *  `None`: the agent's own sign-in, or no start yet.
	 */
	account_id?: string | null,
	/**
	 *  The agent said its usage limit is reached. Cleared when a turn completes or the agent
	 *  starts again, on another account or after the reset.
	 */
	usage_limit?: UsageLimit | null,
};

/**
 *  What the header's pickers and the slash menu show, fetched with `chat_lists` whenever
 *  [`SessionInfo::revision`] changes.
 */
export type SessionLists = {
	controls?: SessionControls,
	revision: number,
	/**  `None` until the agent has started once. */
	capabilities: Capabilities | null,
	options: ConfigOption[],
	commands: SlashCommand[],
	autonomy: AutonomyState,
	/**  What the running session loaded, where its agent reports it. */
	loaded?: SessionLoaded | null,
};

/**
 *  What a running session loaded, as its agent reports it once it starts: MCP servers with
 *  their state, skills, plugins and subagents. Each agent reports what it can: Claude all of it,
 *  Codex its MCP servers, Pi its skills.
 */
export type SessionLoaded = {
	mcp_servers: LoadedMcpServer[],
	skills: string[],
	plugins: LoadedPlugin[],
	agents: string[],
	/**  How many tools the agent offers, MCP tools included. */
	tools: number | null,
};

/**  Where a chat's agent is in its life. */
export type SessionStatus = 
/**  No process. */
"stopped" | "starting" | 
/**  The process is up and no turn runs. */
"ready" | 
/**  Exactly one turn is in flight. */
"running" | 
/**  The agent was asked to cancel; waiting for its reply. */
"cancelling" | "stopping" | 
/**  Could not start; no process. */
"failed" | 
/**  The agent needs its own sign-in; never a live process. */
"auth_required";

export type SetupAction = { type: "visit"; step: SetupStep } | { type: "motion"; value: MotionPreference } | { type: "appearance"; value: AppearancePreference } | { type: "theme"; value: ThemePreference } | { type: "text_size"; value: TextSizePreference } | { type: "project"; project_id: string } | { type: "finish" } | { type: "restart" } | 
/**
 *  Changing the agent clears the default model and thinking level, which belong to the
 *  previous agent.
 */
{ type: "default_agent"; agent_id: string | null } | 
/**  Changing the model clears the default thinking level, which was chosen for the old one. */
{ type: "default_model"; model: string | null } | { type: "default_effort"; effort: string | null } | { type: "default_autonomy"; value: Autonomy } | { type: "automatic_checkpoints"; enabled: boolean } | { type: "notifications"; enabled: boolean } | { type: "keep_awake"; enabled: boolean } | { type: "close_to_tray"; enabled: boolean } | 
/**  Turns configuration sync on or off for one agent on this device. */
{ type: "config_sync_agent"; agent_id: string; enabled: boolean } | 
/**  Turns on or off copying Git-ignored instruction files into new worktree chats. */
{ type: "copy_instructions_to_worktrees"; enabled: boolean } | 
/**  Turns on or off agents' direct edits to project memory. Off keeps review-only proposals. */
{ type: "agent_memory_writes"; enabled: boolean } | 
/**  Turns on or off showing a finished turn's work instead of folding it. */
{ type: "keep_steps_open"; enabled: boolean };

export type SetupCommand = {
	program: string,
	args: string[],
};

export type SetupFile = {
	path: string,
	bytes: number,
};

export type SetupPreferences = {
	revision: number,
	step: SetupStep,
	motion: MotionPreference,
	appearance: AppearancePreference,
	theme: ThemePreference,
	text_size: TextSizePreference,
	completed: boolean,
	first_project_id: string | null,
	/**  Files written before these settings existed read their defaults ([`fill_defaults`]). */
	general: GeneralPreferences,
};

export type SetupSnapshot = {
	preferences: SetupPreferences,
	/**  Stable for this process, even when React remounts or the webview reloads. */
	cold_start: boolean,
	notice: string | null,
};

export type SetupStep = "welcome" | "agents" | "account" | "motion" | "project";

export type SignInChallenge = {
	id: string,
	expires_in: number,
	resend_after: number,
};

export type SignInLink = {
	id: string,
	email: string | null,
};

export type SlashCommand = {
	name: string,
	description: string,
	input_hint: string | null,
};

/**  One check a chat scenario made: its name, whether it held, and what was seen. */
export type SmokeCheck = {
	name: string,
	ok: boolean,
	/**  What the check saw, or why it failed (or did not run). */
	detail: string,
};

/**  What a smoke launch runs: its scenario, with the agent and folder the chat scenarios use. */
export type SmokePlan = {
	scenario: SmokeScenario,
	/**
	 *  The agent the chat scenarios create their chat with: the demo agent for `chat` and
	 *  `chat_reopen`, `AURACODE_SMOKE_AGENT`'s for `agent`; `null` for `stream`.
	 */
	agent_id: string | null,
	/**  `AURACODE_SMOKE_FOLDER`, which the folder picker answers; `null` for `stream`. */
	folder: string | null,
};

/**  What the UI's smoke run found. */
export type SmokeReport = {
	ok: boolean,
	/**
	 *  The scenario that ran; `null` only in a report made before any could (a smoke launch whose
	 *  switches were not valid).
	 */
	scenario: SmokeScenario | null,
	/**  The stream check's measurements; `null` for the chat scenarios. */
	stream: StreamMeasures | null,
	/**  Every check a chat scenario defines, in order; empty for the stream check. */
	checks: SmokeCheck[],
	errors: string[],
};

/**  Which scripted check a smoke launch runs. */
export type SmokeScenario = 
/**  A demo stream, a cancelled stream and a stress burst (`AURACODE_SMOKE=1`). */
"stream" | 
/**
 *  The chat screens against the demo agent in a new data folder, ending with the quit flow
 *  while a turn runs (`AURACODE_SMOKE=chat`).
 */
"chat" | 
/**
 *  The same data folder started again after `chat`: the stored history, the turn the quit
 *  interrupted, the prompt it held, and Resume (`AURACODE_SMOKE=chat-reopen`).
 */
"chat_reopen" | 
/**
 *  One minimal chat with `AURACODE_SMOKE_AGENT`'s agent (`AURACODE_SMOKE=chat` with that set).
 *  For local runs only: a real agent spends the user's quota.
 */
"agent";

export type SteeringAck = {
	message_id: string,
	state: SteeringState,
	detail: string | null,
};

/**  Pending after a crash or a closed turn is unconfirmed, never proof of delivery. */
export type SteeringState = "pending" | "accepted" | "rejected" | "unconfirmed";

/**  Why a turn ended. */
export type StopReason = "end_turn" | "max_tokens" | "max_turn_requests" | "refusal" | 
/**  The agent confirmed a cancel. */
"cancelled" | 
/**  auracode ended the turn without the agent: a force stop, a crash, a quit. */
"interrupted" | "error" | 
/**  A reason auracode does not know (an agent's, or a newer build's). */
"other";

export type StorageState = { state: "ok" } | { state: "paused"; reason: PauseReason; since: number } | { state: "failed"; message: string };

/**  Whether the profile database is saving. */
export type StorageStatus = {
	state: StorageState,
	unsaved_bytes: number,
};

/**  What the stream check measured. */
export type StreamMeasures = {
	/**  Events applied across every stream of the run. */
	events_received: number,
	/**  Frames (`EventBatch`es) received across every stream of the run. */
	frames_received: number,
	/**  Sequence gaps the stream reducer detected. Any gap fails the run. */
	seq_gaps: number,
	/**  Characters of streamed answer text present in the rendered DOM. */
	rendered_chars: number,
	/**  Lowest frame rate over half-second windows of the stress burst. */
	fps_min: number | null,
	/**  Average frame rate over the stress burst. */
	fps_avg: number | null,
};

/**
 *  Settings for the stress view: `orbs` live orbs, a stream at `rate` tokens per second, the aura
 *  field on or off, for `seconds` seconds (0 keeps streaming until the window closes).
 */
export type StressConfig = {
	orbs: number,
	rate: number,
	aura: boolean,
	seconds: number,
};

/**  What a task runs. */
export type TaskKind = 
/**  A subagent with its own conversation. */
"agent" | 
/**  A shell command. */
"command" | 
/**  A kind auracode does not know (an agent's newer kind, or a newer build's). */
"other";

/**  Where a task is in its life. */
export type TaskStatus = "running" | "completed" | "failed" | 
/**  Stopped or killed, or its turn or its agent's process ended before it reported an end. */
"stopped";

/**  One step of a task's work. */
export type TaskStep = {
	step_id: string,
	kind: TaskStepKind,
	/**  A tool's readable title ("Read main.rs"); empty for text. */
	title: string,
	tool_kind: ToolKind | null,
	/**  A tool's status. */
	status: ToolStatus | null,
	/**  A text step's markdown. */
	text: string | null,
	/**  The text was cut to fit the event budget; `blob` holds all of it. */
	truncated: Truncation | null,
};

/**  What a [`TaskStep`] shows. */
export type TaskStepKind = 
/**  A tool call the task made. */
"tool" | 
/**  Text the task's agent wrote. */
"text";

/**  One bounded pull. An empty nonterminal chunk means only that the read wait elapsed. */
export type TerminalChunk = {
	bytes: number[],
	done: boolean,
	exit_code: number | null,
	truncated: boolean,
};

/**
 *  How large the chat's text sets (owner, 4 November 2026: fit more text in, as Codex does).
 *  Compact is the default; Comfortable keeps the earlier, larger size. A file written before this
 *  setting existed, or naming a size this build lacks, reads as Compact ([`fill_defaults`]).
 */
export type TextSizePreference = "compact" | "comfortable";

/**
 *  The desktop's theme: Aura's own neutral palette, or one per supported agent (owner,
 *  3 November 2026). It belongs to the profile on this device, like appearance, and works in both
 *  appearances. Claude Code's is the default (owner, 4 November 2026): a profile that never chose
 *  one, or a file from a newer build that names a theme this build lacks, reads as it
 *  ([`fill_defaults`]). A saved choice, Aura included, is kept.
 */
export type ThemePreference = "aura" | "claude" | "codex" | "grok" | "pi" | "antigravity" | "cursor" | "opencode" | "oh_my_pi" | "hermes";

/**  Token accounting for a turn, when the agent reports it. */
export type TokenUsage = {
	input_tokens: number,
	output_tokens: number,
	/**  Tokens read from the prompt cache (ACP `cachedReadTokens`, Claude `cache_read_input_tokens`). */
	cache_read_tokens: number | null,
	/**
	 *  Tokens written to the prompt cache (ACP `cachedWriteTokens`, Claude
	 *  `cache_creation_input_tokens`).
	 */
	cache_write_tokens: number | null,
	/**  ACP `thoughtTokens`. */
	reasoning_tokens: number | null,
	scope: UsageScope,
};

/**  A tool invocation started by the agent. */
export type ToolCall = {
	tool_call_id: string,
	kind: ToolKind,
	title: string,
	status: ToolStatus,
	locations: ToolLocation[],
	/**  The tool's raw input as the agent sent it, for the expanded view. */
	raw_input: Value | null,
	/**  The tool's own name (ACP `ToolCall.name`). */
	tool_name: string | null,
	/**  ACP tool calls carry content from the start. */
	content: ToolContent[],
	/**  More than entry text was cut to fit the event budget; `blob` holds the original event's JSON. */
	truncated: Truncation | null,
};

/**  Rich content attached to a tool call or update. */
export type ToolContent = { type: "text"; text: string; truncated: Truncation | null } | { type: "diff"; path: string; 
/**  `None` when the file is new. */
old_text: string | null; new_text: string; truncated: Truncation | null } | { type: "terminal"; output: string; exit_code: number | null; truncated: Truncation | null };

export type ToolKind = "read" | "edit" | "delete" | "move" | "search" | "execute" | "think" | "fetch" | "switch_mode" | "other";

export type ToolLocation = {
	path: string,
	line: number | null,
};

export type ToolStatus = "pending" | "in_progress" | "completed" | "failed";

/**
 *  Progress or result for a previously announced [`ToolCall`]. Mirrors ACP's update: `None` keeps a
 *  field; `content: Some(v)` replaces the content, and `Some([])` clears it.
 */
export type ToolUpdate = {
	tool_call_id: string,
	status: ToolStatus | null,
	title: string | null,
	kind: ToolKind | null,
	locations: ToolLocation[] | null,
	raw_input: Value | null,
	/**  ACP `ToolCallUpdateFields.name`. */
	tool_name: string | null,
	content: ToolContent[] | null,
	/**  As on [`ToolCall`]. */
	truncated: Truncation | null,
};

/**  Inline content was cut; `blob` is the sha256 of the full content in the profile's attachments. */
export type Truncation = {
	total_bytes: number,
	blob: string | null,
};

/**  The agent one turn ran on. */
export type TurnAgent = {
	turn_id: string,
	agent_id: string,
	/**  The agent's display name ("Claude Code"). */
	agent_name: string,
};

/**  The answer to a [`UiRequest`], matching its [`UiPrompt`] (`Notify` takes none). */
export type UiAnswer = { type: "confirm"; yes: boolean } | { type: "select"; index: number } | { type: "input"; text: string } | { type: "questions"; answers: UiQuestionAnswer[] } | 
/**  A form submitted (`accept`) with its answered fields, or declined with none. */
{ type: "form"; accept: boolean; values: UiFieldValue[] };

/**  One field of a form. `id` is the schema property's name, which answers use. */
export type UiField = {
	id: string,
	label: string,
	description: string | null,
	required: boolean,
	kind: UiFieldKind,
};

export type UiFieldKind = { type: "text"; format: UiTextFormat | null; min_length: number | null; max_length: number | null; default: string | null } | { type: "number"; integer: boolean; minimum: number | null; maximum: number | null; default: number | null } | { type: "boolean"; default: boolean | null } | 
/**
 *  One choice or, with `multiple`, any number within the bounds. Answers name choices by
 *  position, so shortening a label for display never changes what is sent.
 */
{ type: "choice"; options: string[]; multiple: boolean; min_items: number | null; max_items: number | null; default: number[] };

/**  One answered field. A field left empty has no value at all. */
export type UiFieldValue = {
	id: string,
	value: UiValue,
};

export type UiPrompt = { type: "confirm"; message: string } | { type: "select"; message: string; options: string[] } | { type: "input"; message: string; placeholder: string | null } | { type: "questions"; message: string; questions: UiQuestion[] } | { type: "notify"; message: string } | 
/**
 *  An MCP server's form (MCP elicitation, form mode), answered with [`UiAnswer::Form`].
 *  `source` names the server.
 */
{ type: "form"; message: string; source: string | null; fields: UiField[] } | 
/**
 *  An MCP server asks the user to finish something in the browser (URL mode). Answered
 *  with [`UiAnswer::Confirm`]: yes once the page is opened, no to decline.
 */
{ type: "link"; message: string; source: string | null; 
/**  http or https only. */
url: string };

/**
 *  One question in a grouped prompt. The driver keeps the original native question and maps it by
 *  `id`, so display normalization never changes the key sent back to the agent.
 */
export type UiQuestion = {
	/**  Stable within the request and unique among its questions. */
	id: string,
	header: string,
	question: string,
	options: UiQuestionOption[],
	multi_select: boolean,
	allow_free_text: boolean,
};

/**
 *  One answer per question. A single-select question accepts one option or free text; a
 *  multi-select question accepts multiple options and optional free text. Nothing is preselected.
 */
export type UiQuestionAnswer = {
	question_id: string,
	/**  Distinct indices into the question's options, in their displayed order. */
	selected: number[],
	/**  Nonblank when present, and accepted only when the question allows free text. */
	text: string | null,
};

export type UiQuestionOption = {
	label: string,
	description: string,
};

/**
 *  An agent asks the UI for input that isn't a tool permission (Claude or Cursor questions,
 *  Pi extension UI, ACP elicitation, MCP forms). Never auto-answered.
 */
export type UiRequest = {
	request_id: string,
	prompt: UiPrompt,
};

/**  The string formats MCP forms can ask for. */
export type UiTextFormat = "email" | "uri" | "date" | "date_time";

export type UiValue = { type: "text"; text: string } | { type: "number"; number: number | null } | { type: "boolean"; value: boolean } | 
/**  Positions in the field's options, each at most once. */
{ type: "choices"; selected: number[] };

export type UpdateError = {
	message: string,
};

